head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[gridView > P > sortable]<br/>Header Column 을 클릭 또는 더블 클릭하여 데이터를 정렬할지 설정합니다.",
    "validation" : [
        "sortable=true, sortHeaderDiv=true 이면 showSortableImage 속성은 true 로, sortEvent 속성은 'onclick' 으로 강제 설정되어야 합니다.",
        "sortable=true, accessibility=true 이면 sortHeaderDiv 속성이 true 로 강제 설정되므로 showSortableImage, sortEvent 속성도 연관되어 강제 설정되어야 합니다.",
    ]
}



scwin.onpageload = function () {
    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();

    // 테스트 설명, 유효성 생성
    wf_body_left.getObj("scwin").createValidation(scwin.tData);
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof dlt_bind !== 'undefined') {
        $p.data.remove("dlt_bind");
    }

    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    // 속성별 con_ selectbox 로 각각 독립 설정 (공통 gdl_boolean 바인딩 → value 가 아닌 getText() 로 label('' / 'true' / 'false') 판단)
    //  - con_sortHeaderDiv : '' 미설정 / 'true' (showSortableImage/sortEvent 강제 검증) / 'false'
    //  - con_accessibility : '' 미설정 / 'true' (sortHeaderDiv 강제 → 연관 강제 검증) / 'false'
    let vSortDiv = con_sortHeaderDiv.getText();
    let vAccess = con_accessibility.getText();

    // @spec4 강제 설정은 sortable=true 가 전제이므로 항상 sortable: true 포함
    let properties = {
        sortable: true,
        dataList: "data:dlt_bind",
    };

    // sortHeaderDiv : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    if (vSortDiv === 'true') {
        properties.sortHeaderDiv = true;
    } else if (vSortDiv === 'false') {
        properties.sortHeaderDiv = false;
    }
    // accessibility : 미설정('') 이면 속성 자체를 추가하지 않음(기본 false)
    if (vAccess === 'true') {
        properties.accessibility = true;
    } else if (vAccess === 'false') {
        properties.accessibility = false;
    }

    let lblDesc = 'sortable=true'
        + (vSortDiv === '' ? '' : ', sortHeaderDiv=' + vSortDiv)
        + (vAccess === '' ? '' : ', accessibility=' + vAccess);

    let cList = $c.gcm.createCList(properties);

    // 현재 설정 상태 라벨 (target 생성 전 가장 먼저 생성)
    $c.gcm.createLabel('label="' + lblDesc + '"', '', 'label1');

    // dataList 생성 (4행)
    $c.gcm.createDynamicDataList('', '', 'dlt_bind');

    // target 생성
    await $c.gcm.createBasicGridView(cList, '');
}



// 강제 설정 확인 : target1.options 의 showSortableImage / sortEvent / sortHeaderDiv 실측값을 출력 (@spec4)
//  - sortable=true, sortHeaderDiv=true → showSortableImage=true, sortEvent='onclick' 강제
//  - sortable=true, accessibility=true → sortHeaderDiv=true 강제 → showSortableImage/sortEvent 연관 강제
scwin.btn_checkForced_onclick = function (e) {
    if (typeof target1 === 'undefined') {
        wf_body_bottom.getObj("scwin").setReturnValue("target1 이 생성되지 않았습니다.");
        return;
    }

    wf_body_bottom.getObj("scwin").setReturnValue("[설정] sortable : " + target1.options.sortable + " / sortHeaderDiv : " + target1.options.sortHeaderDiv + " / accessibility : " + target1.options.accessibility);
    wf_body_bottom.getObj("scwin").setReturnValue("[강제] showSortableImage : " + target1.options.showSortableImage + " / sortEvent : " + target1.options.sortEvent);
}
